#!/usr/bin/env bash

# AI: below section was generated by an AI
# Installs systemd hooks that report Linux boot, sleep, resume, and shutdown
# transitions to the BC250Power usermod through WLED's JSON API.
set -euo pipefail

readonly DEFAULT_WLED_URL="http://loungepc-leds.home"
readonly CONFIG_FILE="/etc/bc250-wled.conf"
readonly NOTIFIER="/usr/local/sbin/bc250-wled-state"
readonly ONLINE_UNIT="/etc/systemd/system/bc250-wled-online.service"
readonly SLEEP_UNIT="/etc/systemd/system/bc250-wled-sleep.service"

if [[ ${EUID} -ne 0 ]]; then
  echo "Run this installer as root, for example: sudo $0" >&2
  exit 1
fi

for command_name in curl install systemctl; do
  if ! command -v "${command_name}" >/dev/null 2>&1; then
    echo "Required command is missing: ${command_name}" >&2
    exit 1
  fi
done

wled_url="${1:-${DEFAULT_WLED_URL}}"
wled_url="${wled_url%/}"
if [[ ! ${wled_url} =~ ^http://[A-Za-z0-9._:-]+$ ]]; then
  echo "WLED URL must be an HTTP origin such as http://loungepc-leds.home" >&2
  exit 1
fi

install -d -m 0755 /usr/local/sbin

cat >"${NOTIFIER}" <<'NOTIFIER_EOF'
#!/usr/bin/env bash
set -u

readonly CONFIG_FILE="/etc/bc250-wled.conf"
state="${1:-}"

case "${state}" in
  running|sleeping|shutting_down) ;;
  *)
    echo "Usage: $0 {running|sleeping|shutting_down}" >&2
    exit 2
    ;;
esac

if [[ -z ${WLED_URL:-} && -r ${CONFIG_FILE} ]]; then
  WLED_URL="$(sed -n 's/^WLED_URL=//p' "${CONFIG_FILE}" | head -n 1)"
fi

WLED_URL="${WLED_URL:-}"
WLED_URL="${WLED_URL%/}"
if [[ ! ${WLED_URL} =~ ^http://[A-Za-z0-9._:-]+$ ]]; then
  logger -t bc250-wled "No valid WLED_URL is configured" 2>/dev/null || true
  exit 0
fi

payload="{\"BC250Power\":{\"osEvent\":\"${state}\"}}"
attempts=2
delay_seconds=1
if [[ ${state} == running ]]; then
  attempts=10
  delay_seconds=2
fi

for ((attempt = 1; attempt <= attempts; attempt++)); do
  if curl --fail --silent --show-error \
    --connect-timeout 2 --max-time 3 \
    --header 'Content-Type: application/json' \
    --data "${payload}" "${WLED_URL}/json/state" >/dev/null; then
    exit 0
  fi
  if ((attempt < attempts)); then
    sleep "${delay_seconds}"
  fi
done

# OS transitions must proceed even when WLED is offline.
logger -t bc250-wled "Could not report ${state} to ${WLED_URL}" 2>/dev/null || true
exit 0
NOTIFIER_EOF
chmod 0755 "${NOTIFIER}"

printf 'WLED_URL=%s\n' "${wled_url}" >"${CONFIG_FILE}"
chmod 0644 "${CONFIG_FILE}"

cat >"${ONLINE_UNIT}" <<'ONLINE_EOF'
[Unit]
Description=Report BC250 OS state to WLED
Wants=network-online.target
After=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
EnvironmentFile=/etc/bc250-wled.conf
ExecStart=/usr/local/sbin/bc250-wled-state running
ExecStop=/usr/local/sbin/bc250-wled-state shutting_down
TimeoutStartSec=50
TimeoutStopSec=10

[Install]
WantedBy=multi-user.target
ONLINE_EOF
chmod 0644 "${ONLINE_UNIT}"

cat >"${SLEEP_UNIT}" <<'SLEEP_EOF'
[Unit]
Description=Report BC250 sleep state to WLED
Before=sleep.target
StopWhenUnneeded=yes

[Service]
Type=oneshot
RemainAfterExit=yes
EnvironmentFile=/etc/bc250-wled.conf
ExecStart=/usr/local/sbin/bc250-wled-state sleeping
ExecStop=/usr/local/sbin/bc250-wled-state running
TimeoutStartSec=10
TimeoutStopSec=50

[Install]
WantedBy=sleep.target
SLEEP_EOF
chmod 0644 "${SLEEP_UNIT}"

systemctl daemon-reload
systemctl enable bc250-wled-online.service bc250-wled-sleep.service
if systemctl is-active --quiet bc250-wled-online.service; then
  WLED_URL="${wled_url}" "${NOTIFIER}" running
else
  systemctl start bc250-wled-online.service
fi

echo "BC250 WLED OS integration installed for ${wled_url}."
echo "The current OS state has been reported as running."
# AI: end
